import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 300;

const COLORS = {
  orange: "#FF6B35",
  lightOrange: "#FF8C5A",
  white: "#FFFFFF",
  offWhite: "#F5F5F5",
  mutedWhite: "rgba(255,255,255,0.6)",
  bg: "#0A0A0A",
  cardBg: "rgba(255,255,255,0.04)",
  cardBorder: "rgba(255,255,255,0.10)",
};

const TRANSITION = 15;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const WebinarCard: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: _fps } = useVideoConfig();

  // Card entrance
  const cardProgress = spring({
    frame,
    fps: _fps,
    delay: 5,
    config: { damping: 200 },
  });

  // Logo entrance
  const logoProgress = spring({
    frame,
    fps: _fps,
    delay: 18,
    config: { damping: 200 },
  });

  // Divider line
  const lineProgress = spring({
    frame,
    fps: _fps,
    delay: 28,
    config: { damping: 200 },
  });

  // "Apify Webinar" label
  const labelProgress = spring({
    frame,
    fps: _fps,
    delay: 35,
    config: { damping: 200 },
  });

  // Main title
  const titleProgress = spring({
    frame,
    fps: _fps,
    delay: 48,
    config: { damping: 200 },
  });

  // Subtitle line 1
  const sub1Progress = spring({
    frame,
    fps: _fps,
    delay: 62,
    config: { damping: 200 },
  });

  // Subtitle line 2
  const sub2Progress = spring({
    frame,
    fps: _fps,
    delay: 72,
    config: { damping: 200 },
  });

  // Timer placeholder area
  const timerProgress = spring({
    frame,
    fps: _fps,
    delay: 85,
    config: { damping: 200 },
  });

  const cardWidth = 1760;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Main Card */}
        <div
          style={{
            width: cardWidth,
            opacity: cardProgress,
            transform: `translateY(${interpolate(cardProgress, [0, 1], [80, 0])}px) scale(${interpolate(cardProgress, [0, 1], [0.96, 1])})`,
            backgroundColor: "rgba(10, 6, 18, 0.82)",
            backdropFilter: "blur(32px)",
            borderRadius: 40,
            border: "2px solid rgba(255,255,255,0.10)",
            padding: "72px 96px 80px 96px",
            boxShadow:
              "0 40px 120px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.04) inset",
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            gap: 0,
          }}
        >
          {/* Logo */}
          <div
            style={{
              opacity: logoProgress,
              transform: `translateY(${interpolate(logoProgress, [0, 1], [30, 0])}px)`,
              marginBottom: 52,
            }}
          >
            <Img
              src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
              style={{ height: 64, width: "auto" }}
            />
          </div>

          {/* Divider */}
          <div
            style={{
              width: "100%",
              height: 2,
              backgroundColor: "rgba(255,255,255,0.08)",
              borderRadius: 1,
              marginBottom: 52,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                width: `${interpolate(lineProgress, [0, 1], [0, 100])}%`,
                height: "100%",
                background:
                  "linear-gradient(90deg, rgba(255,107,53,0.8), rgba(255,140,90,0.4), rgba(255,255,255,0.1))",
                borderRadius: 1,
              }}
            />
          </div>

          {/* "Apify Webinar" badge label */}
          <div
            style={{
              opacity: labelProgress,
              transform: `translateX(${interpolate(labelProgress, [0, 1], [-30, 0])}px)`,
              marginBottom: 28,
            }}
          >
            <span
              style={{
                display: "inline-block",
                backgroundColor: "rgba(255,107,53,0.12)",
                border: "1.5px solid rgba(255,107,53,0.45)",
                borderRadius: 12,
                padding: "10px 32px",
                fontSize: 32,
                fontWeight: 700,
                color: COLORS.orange,
                letterSpacing: "0.18em",
                textTransform: "uppercase",
              }}
            >
              Apify Webinar
            </span>
          </div>

          {/* Main Title */}
          <div
            style={{
              opacity: titleProgress,
              transform: `translateY(${interpolate(titleProgress, [0, 1], [40, 0])}px)`,
              marginBottom: 24,
            }}
          >
            <h1
              style={{
                margin: 0,
                fontSize: 92,
                fontWeight: 800,
                color: COLORS.white,
                lineHeight: 1.05,
                letterSpacing: "-0.02em",
              }}
            >
              Expanding your Shopify
            </h1>
          </div>

          {/* Subtitle line 1 */}
          <div
            style={{
              opacity: sub1Progress,
              transform: `translateY(${interpolate(sub1Progress, [0, 1], [30, 0])}px)`,
              marginBottom: 8,
            }}
          >
            <h2
              style={{
                margin: 0,
                fontSize: 92,
                fontWeight: 800,
                color: COLORS.white,
                lineHeight: 1.05,
                letterSpacing: "-0.02em",
              }}
            >
              store to{" "}
              <span
                style={{
                  background: `linear-gradient(90deg, ${COLORS.orange}, ${COLORS.lightOrange})`,
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                }}
              >
                new markets
              </span>
            </h2>
          </div>

          {/* Decorative sub-line */}
          <div
            style={{
              opacity: sub2Progress,
              transform: `translateY(${interpolate(sub2Progress, [0, 1], [20, 0])}px)`,
              marginBottom: 64,
              marginTop: 16,
            }}
          >
            <p
              style={{
                margin: 0,
                fontSize: 36,
                fontWeight: 500,
                color: "rgba(255,255,255,0.45)",
                letterSpacing: "0.01em",
              }}
            >
              Powered by web scraping &amp; data intelligence
            </p>
          </div>

          {/* Timer placeholder */}
          <div
            style={{
              opacity: timerProgress,
              transform: `translateY(${interpolate(timerProgress, [0, 1], [20, 0])}px)`,
              width: "100%",
            }}
          >
            {/* Thin separator */}
            <div
              style={{
                width: "100%",
                height: 1.5,
                backgroundColor: "rgba(255,255,255,0.07)",
                borderRadius: 1,
                marginBottom: 40,
              }}
            />

            {/* Timer area — empty box for user to add their timer */}
            <div
              style={{
                width: "100%",
                minHeight: 120,
                borderRadius: 20,
                border: "2px dashed rgba(255,255,255,0.12)",
                backgroundColor: "rgba(255,255,255,0.02)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {/* Timer goes here — intentionally left empty */}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 20 })}
      />

      {/* Main webinar card — holds for the full duration */}
      <TransitionSeries.Sequence durationInFrames={260 + TRANSITION}>
        <WebinarCard />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
